StructuralRule.Notes:
Ideally would use reaches/reachedBy, but couldn't do due to scope limitations, so just picked a few simple variations

Example:

var t = false;
fc.runIO(function(){
  fc2();
});

function fc2(){
  t = true;
}
if (t){
  //do something
}

