CharacterizationRule.StructuralMatch:
FunctionCall fc: possibleTargets contains [Function: name == "query" 
        and (
            enclosingClass.supers contains [Class: name == "Sequelize"]
            or fc.instance.possibleTypes contains [Type: name == "Sequelize"]
        )
    ]

FunctionCall fc: possibleTargets contains [Function: name matches "find(All|AndCountAll|ByPk|CreateFind|One|OrBuild|OrCreate)" 
        and (
            enclosingClass.supers contains [Class: name matches "Sequelize|Model"]
            or fc.instance.possibleTypes contains [Type: name == "Sequelize"]
        )
    ]

