FunctionModel.Code:
function promisify(original) {
    return function (...args) {
        return new Promise((resolve, reject) => {
            original(args, (err, result) => {
                if (err) {
                    reject(err);
                } else {
                    resolve(result);
                }
            });
        });
    };
}

