CharacterizationRule.Script:
var ns = new Namespace("");
var JavaScriptPreprocessingFiles = [];
for each (var xml in program.xml) {
    if (xml.name() == "plist") {
        for each (var node in xml..ns::key) {
            if (node.text() == "NSExtensionJavaScriptPreprocessingFile") {
                var node_parent = node.parent();
                if (node_parent === null || node_parent === undefined) continue;
                var node_sibling = node_parent().children()[ node.childIndex() + 1 ];
                if (node_sibling === null || node_sibling === undefined) continue;
                JavaScriptPreprocessingFiles[JavaScriptPreprocessingFiles.length] = node_sibling.text() + ".js";
            }
        }
    }
}
if (JavaScriptPreprocessingFiles.length > 0) {
    rule.StructuralMatch = String(rule.StructuralMatch).replace(/FFY_JSFILENAMES/, JavaScriptPreprocessingFiles.join('|'));
}

