                    name == "logger"
                    and namespace.name == "Handlebars"
                ]
            ]
            or namespace.name == "Handlebars"
        )
    ]
    and fc.arguments[0] is [Expression e: 
        not (
            /* check for DEBUG mode in 3.x */
            e is [FieldAccess fa: 
                fa.field.name == "DEBUG"
                /* 
                * honestly I can't be bothered to go about testing types
                * when this is only possible with really old versions of the library
                * so I'll just check the instance name to save time.
                */ 
                and fa.instance is [FieldAccess: field.name == "logger"
