CharacterizationRule.StructuralMatch:
AssignmentStatement:
    lhs is [FieldAccess:
        name == "setHeaders"
        and instance is [Expression options:
            enclosingFunction contains [FunctionCall:
                possibleTargets contains [Function:
                    name == "static"
                ]
                and instance.possibleTypes contains [Type: name == "e~~wrapper"]
                and arguments[1] is options
            ]
        ]
    ]
    and rhs.possibleFunctionTargets contains [Function:
        parameters[1] is [Variable path:]
    ]

FunctionCall fc:
    possibleTargets contains [Function:
        name == "render"
        and enclosingClass.supers contains [Class:
            name == "Application"
        ]
    ]
    and arguments contains [Expression:
        possibleFunctionTargets contains [Function:
            parameters[0] is [Variable err:]
        ]
    ]

