CharacterizationRule.StructuralMatch:
FunctionCall fc: fc.possibleTargets contains [Function f:
        f.name matches "get|post|patch|put|jsonp|head|delete"
    ]
    /* possibleHeapPaths matching too broadly */
    and fc.instance is [Location: name == "$http"]
    and fc.arguments[0] is [Expression inArg: ]

FunctionCall fc: fc.possibleTargets contains [Function f:
        f.name matches "get|post|patch|put|jsonp|head|delete"
    ]
    /* possibleHeapPaths matching too broadly */
    and fc.instance is [FieldAccess: field.name == "$http"]
    and fc.arguments[0] is [Expression inArg: ]

FunctionCall fc: fc.possibleTargets contains [Function: name matches "(start|end)Symbol"
        and (
            possibleHeapPaths contains [String str: str == "$interpolateProvider"]
            or fc.instance is [Location: name == "$interpolateProvider"]
            /* matches against last function call in builder-style call $interpolateProvider.startSymbol('##').endSymbol(userInput); */
            or fc.instance is [FunctionCall: possibleTargets contains [Function: name matches "(start|end)Symbol"]]
        )
    ]
    and fc.arguments.length == 1
    and fc.arguments[0] is [Expression inArg: ]

FunctionCall fc: fc.possibleTargets contains [Function: name matches "(start|end)Symbol"
        and (
            possibleHeapPaths contains [String str: str == "$interpolateProvider"]
            or fc.instance is [FieldAccess: field.name == "$interpolateProvider"]
            /* matches against last function call in builder-style call $interpolateProvider.startSymbol('##').endSymbol(userInput); */
            or fc.instance is [FunctionCall: possibleTargets contains [Function: name matches "(start|end)Symbol"]]
        )
    ]
    and fc.arguments.length == 1
    and fc.arguments[0] is [Expression inArg: ]

FunctionCall fc: possibleTargets contains [Function:
    name == "trustAs"
    and possibleHeapPaths contains [String str:
        str matches "\$sce(Delegate)?"]
    ]
    /* already have a passthrough for $sce.HTML and $sce.RESOURCE_URL as the 0th arg, so don't duplicate */
    and not arguments[0] is [Location:
        name == "HTML" or name == "RESOURCE_URL"
    ]
    and arguments[1] is [Expression e: ]

FunctionCall fc: possibleTargets contains [Function:
    name == "trustAs"
    and possibleHeapPaths contains [String str:
        str matches "\$sce(Delegate)?"]
    ]
    /* already have a passthrough for $sce.HTML and $sce.RESOURCE_URL as the 0th arg, so don't duplicate */
    and not arguments[0] is [FieldAccess:
        field.name == "HTML" or field.name == "RESOURCE_URL"
    ]
    and arguments[1] is [Expression e: ]

