CharacterizationRule.Notes:
Labels top-level resolver functions (Query/Mutation fields).
Resolver functions are invoked by Apollo to populate the data for a field in a GraphQL schema.

This rules labels resolver functions that follow the following common pattern:

const resolvers = {
    Query: {
        user: async (parent, args, context, info) => {
            return users.find(user => user.id === args.id);
        }
    }
}

Matched functions are labeled as apollo server entrypoint candidates. A rulescript later attempts 
to determine if ApolloServer is actually used and adds the confirming label 'apollo-server.entrypoint' 
if evidence of ApolloServer usage is found.

ScriptDefinitions.ScriptDefinition:
/**
 * Turn a sink rule into dual-sink by removing issues when the second sink rule did not trigger at the same location.
 * @param vulns A list of vulns to check. Typically through `getVulnerabilities()`
 * @param mainSinkRule Rule ID of the sink rule to be "converted" to dual-sink.
 * @param secondarySinkRule Rule ID of the secondary sink rule. Typically a "Fortify Internal" rule.
 * @param removeSecondary Boolean (defaults to true). If true, remove all issues by the secondary sink rule. To avoid removing these issues, set it to false explicitly.
*/
function enforceDualSink(vulns, mainSinkRule, secondarySinkRule, removeSecondary) {
    if (mainSinkRule == null || mainSinkRule == "" || secondarySinkRule == null || secondarySinkRule == "" || mainSinkRule == secondarySinkRule)
        return;

    var mainVulns = {};
    var secondaryVulns = {};
    for each (var vuln in vulns) {
        if (vuln == null || vuln.getPrimaryFile() == null || vuln.getPrimaryLine() == null || vuln.getAnalyzerName() != "dataflow")
            continue;
        var sinkLocation = String(vuln.getPrimaryFile()) + ":" + String(vuln.getPrimaryLine());
        if (vuln.getPrimaryCall() != null) {
            sinkLocation += ":"+vuln.getPrimaryCall().getName();
        }
        var ruleID = String(vuln.getRule().getIdentifier());
        if (ruleID.startsWith(mainSinkRule)) {
            if (!(sinkLocation in mainVulns))
                mainVulns[sinkLocation] = new Array();
            mainVulns[sinkLocation].push(vuln);
        }
        else if (ruleID.startsWith(secondarySinkRule)) {
            if (!(sinkLocation in secondaryVulns))
                secondaryVulns[sinkLocation] = new Array();
            secondaryVulns[sinkLocation].push(vuln);
        }
    }
    for each (var loc in Object.keys(mainVulns)) {
        if (!(loc in secondaryVulns)) {
            for each (var vuln in mainVulns[loc]) {
                vuln.remove();
            }
        }
    }
    if (removeSecondary !== false) {
        for each (var loc in Object.keys(secondaryVulns)) {
            for each (var vuln in secondaryVulns[loc]) {
                vuln.remove();
            }
        }
    }
}

/**
 * Applies a dataflow condition to a source rule. The source rule is only valid if a given sink rule triggered at the same location as the source rule. If determined invalid, all dataflow issues from the source rules will be removed.
 * @param vulns A list of vulns to check. Typically through `getVulnerabilities()`
 * @param sourceRuleID Rule ID of the source rule to be checked.
 * @param sinkRuleID Rule ID of the utility sink rule. Typically a "Fortify Internal" rule.
 * @param removeSecondary Boolean (defaults to true). If true, remove all issues by the secondary sink rule. To avoid removing these issues, set it to false explicitly.
*/
function enforceConditionalTaintSource(vulns, sourceRuleID, sinkRuleID, removeSecondary) {
    if (sourceRuleID == null || sourceRuleID == "" || sinkRuleID == null || sinkRuleID == "")
        return;

    var mainVulns = {};
    var secondaryVulns = {};
    for each (var vuln in vulns) {
        if (vuln == null || vuln.getPrimaryFile() == null || vuln.getPrimaryLine() == null || vuln.getTaintSource() == null || vuln.getAnalyzerName() != "dataflow")
            continue;

        var taintSource = vuln.getTaintSource()
        if (taintSource.getFile() == null || taintSource.getLine() == null)
            continue;
        var taintSourceLoc = String(taintSource.getFile()) + ":" + String(taintSource.getLine())
        var taintSinkLoc = String(vuln.getPrimaryFile()) + ":" + String(vuln.getPrimaryLine());
        var vulnSourceRuleID = String(vuln.getSourceRule().getIdentifier());
        var vulnSinkRuleID = String(vuln.getRule().getIdentifier());
        if (vulnSourceRuleID.startsWith(sourceRuleID)) {
            if (!(taintSourceLoc in mainVulns))
                mainVulns[taintSourceLoc] = new Array();
            mainVulns[taintSourceLoc].push(vuln);
        }
        if (vulnSinkRuleID.startsWith(sinkRuleID)) {
            if (!(taintSinkLoc in secondaryVulns))
                secondaryVulns[taintSinkLoc] = new Array();
            secondaryVulns[taintSinkLoc].push(vuln);
        }
    }

    for each (var loc in Object.keys(mainVulns)) {
        if (!(loc in secondaryVulns)) {
            for each (var vuln in mainVulns[loc]) {
                vuln.remove();
            }
        }
    }
    if (removeSecondary !== false) {
        for each (var loc in Object.keys(secondaryVulns)) {
            for each (var vuln in secondaryVulns[loc]) {
                vuln.remove();
            }
        }
    }
}

var allVulns = getVulnerabilities();
enforceDualSink(allVulns, "32AA416A-B306-46E1-8DFF-377D485762B0", "40C5F57A-2AFB-4DA6-BE8A-07A3A34E23E6");
enforceDualSink(allVulns, "689B40A2-96AD-469E-BACF-1683EA7CC0FF", "40C5F57A-2AFB-4DA6-BE8A-07A3A34E23E6");
enforceDualSink(allVulns, "0CF667FE-9BF7-4A71-B711-8D1F4BB0A5B6", "40C5F57A-2AFB-4DA6-BE8A-07A3A34E23E6");
enforceConditionalTaintSource(allVulns, "7B478806-90E1-4CD1-8FFD-7C30ED7522B5", "40C5F57A-2AFB-4DA6-BE8A-07A3A34E23E6");

Description.Explanation:
Azure Cloud access control errors occur when:

1. Data enters a program from an untrusted source.
    <Paragraph>
In this case the data enters at <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/>.
    </Paragraph>

2. The data is used to view/modify/delete unauthorized queue/blob and its messages/contents.
    <Paragraph>
In this case the data is used by <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
    </Paragraph>

<b>Example 1:</b> The following code deletes the given queue and its messages.

    <pre>
    ...
    var queueName = queryStringData['name'];
    var queueSvc;
    queueSvc = azureStorage.createQueueService();
    ...
    queueSvc.deleteQueue(queueName, option, function(error, response){
      if(!error){
          // all the messages has been deleted
      }
    });
    ...
    </pre>

<b>Example 2:</b> The following code deletes the given blob container and its contents.

    <pre>
    ...
    var containerName = queryStringData['name'];
    var blobSvc;
    blobSvc = azureStorage.createBlobService();
    ...
    blobSvc.deleteContainer(containerName, function (error, response) {
      if (!error) {
          // all the content in the given container has been deleted
      }
    });
    ...
    </pre>

Although the code in <code>Example 1</code> and <code>Example 2</code> delete the given queue/blob container and its messages/contents that belong to the current user/program, an attacker may delete any queue/blob for that Azure account. Because the code in this example does not check to ensure that the user/program has permission to clear the requested queue/blob, it will clear queue/blob, even if it does not belong to the current user/program.

Description.Recommendations:
Rather than relying on the presentation layer to restrict values submitted by the user, access control should be handled by the application and database layers. Under no circumstances should a user be allowed to retrieve or modify a row in the database without the appropriate permissions. Every query that accesses the database should enforce this policy, which can often be accomplished by simply including the current authenticated username as part of the query.

<b>Example 2:</b> The following code implements the same functionality as <code>Example 1</code> but imposes an additional constraint to verify that the invoice belongs to the currently authenticated user.

<pre>
	...
	var id = document.form.invoiceID.value;
	var user = document.form.user.value;
	var query = "SELECT * FROM invoices WHERE id = ? AND user = ?";
	db.transaction(function (tx) {
		tx.executeSql(query,[id,user]);
		}
	)
	...
</pre>

Description.Explanation:
Certain frameworks such as AngularJS limit the protocols that may be set for links to other sites and images. This is primarily to prevent inline JavaScript from running, which may lead to additional cross-site scripting vulnerabilities within the application.

<b>Example 1:</b> The following changes the default allow list of protocols in AngularJS to also allow image HTML elements to allow inline JavaScript.
<pre>
myModule.config(function($compileProvider){
    $compileProvider.imgSrcSanitizationWhitelist(/^(http(s)?|javascript):.*/);
});
</pre>

Strict Contextual Escaping (SCE) is a mechanism in AngularJS applications that helps protect the application from attackers. This can prevent many attack vectors across different types of vulnerabilites. The most prominent protection is against certain types of cross-site scripting attacks. In this application, this protection mechanism is specifically disabled.

<b>Example 1:</b> In this example we disable SCE on a module.
<pre>
myModule.config(function($sceProvider){
  $sceProvider.enabled(false);
});
</pre>

Command injection vulnerabilities take two forms:

- An attacker can change the command that the program executes: the attacker explicitly controls what the command is.

- An attacker can change the environment in which the command executes: the attacker implicitly controls what the command means.

In this case, we are primarily concerned with the first scenario, the possibility that an attacker may be able to control the command that is executed. Command injection vulnerabilities of this type occur when:

1. Data enters the application from an untrusted source.
<Paragraph>
In this case, the data enters at <Replace key="SourceFunction" link="SourceLocation"/> in <Replace key="SourceLocation.file"/> on line <Replace key="SourceLocation.line"/>.
</Paragraph>
<IfDef var="ConditionalDescriptions">
 <Paragraph>
  <ConditionalText condition="taint:number">
Even though the data in this case is a number, it is unvalidated and thus still considered malicious, hence the vulnerability is still reported but with reduced priority values.
  </ConditionalText>
 </Paragraph>
</IfDef>

2. The data is used as or as part of a string representing a command that is executed by the application.
<Paragraph>
In this case, the command is executed by <Replace key="SinkFunction" link="SinkLocation"/> in <Replace key="SinkLocation.file"/> on line <Replace key="SinkLocation.line"/>.
</Paragraph>
3. By executing the command, the application gives an attacker a privilege or capability that the attacker would not otherwise have.

<b>Example 1:</b> The following code from a system utility uses the environment variable <code>APPHOME</code> to determine the directory in which it is installed and then executes an initialization script based on a relative path from the specified directory.

<pre>
var cp = require('child_process');
  ...
  var home = process.env('APPHOME');
  var cmd = home + INITCMD;
  child = cp.exec(cmd, function(error, stdout, stderr){
    ...
  });
  ...
</pre>

The code in <code>Example 1</code> allows an attacker to execute arbitrary commands with the elevated privilege of the application by modifying the system property <code>APPHOME</code> to point to a different path containing a malicious version of <code>INITCMD</code>. Since the program does not validate the value read from the environment, if an attacker can control the value of the system property <code>APPHOME</code>, then they can fool the application into running malicious code and take control of the system.

<b>Example 2:</b> The following code is from an administrative web application designed to allow users to kick off a backup of an Oracle database using a batch-file wrapper around the <code>rman</code> utility. The script <code>rmanDB.bat</code> accepts a single command line parameter, which specifies the type of backup to perform. Because access to the database is restricted, the application runs the backup as a privileged user.

<pre>
var cp = require('child_process');
var http = require('http');
var url = require('url');

function listener(request, response){
  var btype = url.parse(request.url, true)['query']['backuptype'];
  if (btype !== undefined){
    cmd = "c:\\util\\rmanDB.bat" + btype;
    cp.exec(cmd, function(error, stdout, stderr){
      ...
    });
  }
  ...
}
...
http.createServer(listener).listen(8080);
</pre>

The problem here is that the program does not do any validation on the <code>backuptype</code> parameter read from the user apart from verifying its existence. After the shell is invoked, it may allow for the execution of multiple commands, and due to the nature of the application, it will run with the privileges necessary to interact with the database, which means whatever command the attacker injects will run with those privileges as well.

<b>Example 3:</b> The following code is from a web application that provides an interface through which users can update their password on the system. Part of the process for updating passwords in certain network environments is to run a <code>make</code> command in the <code>/var/yp</code> directory.

<pre>
...
require('child_process').exec("make", function(error, stdout, stderr){
  ...
});
...
</pre>

The problem here is that the program does not specify an absolute path for <code>make</code> and fails to clean its environment prior to executing the call to <code>child_process.exec()</code>. If an attacker can modify the <code>$PATH</code> variable to point to a malicious binary called <code>make</code> and cause the program to be executed in their environment, then the malicious binary will be loaded instead of the one intended. Because of the nature of the application, it runs with the privileges necessary to perform system operations, which means the attacker's <code>make</code> will now be run with these privileges, possibly giving the attacker complete control of the system.

Description.Recommendations:
Enable the <code>SameSite</code> attribute when creating session cookies. To do this, set the <code>SameSite</code> field to <code>Strict</code> or <code>Lax</code> in your cookie configuration.

<b>Example 2:</b> The following code enables the <code>SameSite</code> attribute for session cookies.
<pre>
app.get('/', function (req, res) {
    ...
    res.cookie('name', 'Foo', { sameSite: "Strict" });
    ...
}
</pre>

Furthermore, Fortify recommends that developers continue to add traditional Cross-Site Request Forgery (CSRF) mitigations to the site along with the <code>SameSite</code> attribute. Many users might use older browser versions to access the site. Older browser versions do not suppport the <code>SameSite</code> attribute.

